async function isAllowed(userId) {
  const window = Math.floor(Date.now() / 60000);
  const key = `rate:${userId}:${window}`;
  const count = await redis.incr(key);
  if (count === 1) {
    await redis.expire(key, 60); // first hit in this window: set the TTL
  }
  return count <= 100;
}
